t(38, 1325, """{Yaptıkları her amelin önüne geçtik ve onu saçılmış toz zerrelerine çevirdik}""")
h(38, 1700, """Allah'ın gazabının delillerinden: Büyük bir kullukla ve uzun rekâtlarla birlikte zulüm!""")
t(38, 2525, """Sen hâlâ İblis'in oğlusun, sen de hâlâ İblis'in kızısın; ne sen babanın oğlusun ne de sen babanın kızısın! Onlar insanların iblisleridir; erkeklerinin sıfatı da kadınlarının sıfatı da bilinir; insanlar arasında kimi gizli kimi açıktadır.""")

# ───────── Sayfa 39 ─────────
h(39, 600, """En büyük zulüm, Allah'ın kullarından bir kula karşı şeytanla ittifak etmendir!""")
t(39, 1345, """İnsanların çoğunda ikinci cahiliye hâlâ sürüyor; onlara ibadetin başının rekât sayısı ve süresinin uzunluğu olduğunu anlatmış! Rekâtların çokluğu ve süresinin uzunluğu hayır, bereket ve büyük sevaplar olsa da; insanlar anlamak ile hiç anlamamak arasındadır.""")
h(39, 1900, """En büyük zulüm, bir kulun aklını bozman ve böylece onun ibadetini bozmandır!""")

# ───────── Sayfa 40 ─────────
h(40, 500, """En büyük zulüm, tecrübenin yokluğu ve aklın zannıdır!""")
t(40, 1340, """Bunun dışında olan, insanın etrafında olup biteni anladığı vehmidir""")
h(40, 1800, """Gözlerinle, kulaklarınla, ellerinle ve ayaklarınla bizzat görmedikçe Allah'ın eşyadaki hikmetini anlamayacaksın!""")
t(40, 2550, """Bu yüzden insanlar, insanlar içinde derece derecedir""")

# ───────── Sayfa 41 ─────────
h(41, 500, """İnsanlar bizzat görmedikleri ve tecrübe etmedikleri şeyi bilmediklerinde hükümleri anlamazlar""")
t(41, 1320, """Şaşılacak şey, savaşçının karşılaştığına şaşmasıdır! Ateşkes isteyen savaşçıya şaşarım! Dinlenme ister! Kısa da olsa bir uyuklama ister! Bir dost umar! Nerede ona?! Karanlık nasıl aydınlatsın, düşman ben nasıl karşılık versin, savaşçının bedeni bir saat nasıl sükûn bulsun, gözü uyku dışında nasıl dalsın, sükûnet akılda bir günlüğüne bile nasıl doğsun?! Kolay bir yol temenni eden savaşçıya şaşarım; insanların aralarında paylaştığı bir sıcaklığı uman savaşçıya şaşarım; hep dünya kuyruğunun sonunda duran ve yorulan savaşçıya şaşarım! Kalk; bu senin kaderindir ve seni bırakmayacak. Gözyaşı olmadan, gam olmadan ve Allah'tan başka kimseden umut olmadan öl; çünkü sen yeryüzünde bir düşmansın ve düşman kalacaksın. Yoksa kılıcını sat ve düşmanlarla birlikte düşman ol.""")
h(41, 2100, """Doğrudan ve yanlıştan söz eden bir savaşçıdır; savaşçı ise düşmandır; şaşılacak şey ise ..""")

# ───────── Sayfa 42 ─────────
t(42, 395, """Allah Teâlâ'nın izniyle geri dönecek günler; kalbin maraton yarışından durduğu, nefsin günlük soluk soluğa koşudan durduğu ve ruhun her saat parçalanmaktan durduğu günler! 36 poz .. Fotoğrafları teslim alırken sorduğumuz ilk soru şuydu: Kaç fotoğraf sağlam çıktı?! Parayı ödemeden önce bütün fotoğrafları görmek için eve dönmeyi bile beklemezdik!""")
t(42, 1695, """Resûlullah'a (s.a.v.) yalan isnat etmek ne zamana kadar?!!
“Kim her gece Vâkıa Sûresi'ni okursa ona asla yoksulluk isabet etmez” ifadesi Peygamber'e (s.a.v.) nispet edilen bir ifadedir ve senedi ona (s.a.v.) kadar sahih değildir.""")
h(42, 2200, """… Resûlullah'a (s.a.v.) yalan isnat etmek!""")

# ───────── Sayfa 43 ─────────
t(43, 555, """Çözüm yok .. Kavrayan kavradı; vehmi isteyen de ona kolayca yöneltilecek""")
h(43, 1000, """Yalnızca Allah'a ait olmayan bir kalp, ölüme dek paramparça olacaktır!""")
t(43, 1785, """🔴 İnsanın aklına, bilincine ve geleceğine komplo kuran küresel eğitim sistemi
🔴 İnsan bedenine kesinlikle elverişli olmayan kirli gıda
🔴 Öldürücü ilaçlar
🔴 Faydalı hareketi engelleyen günlük hayat düzeni...""")
h(43, 2300, """İnsanı paramparça etmenin kaynaklarını kurutmak.""")

# ───────── Sayfa 44 ─────────
t(44, 695, """Gıda üretimindeki felaket boyutundaki küresel sağlık manzarası altında pirinç, undan %4647656757755 oranında daha güvenli olan sığınağındır. Çoğaltma, israf etme .. tabii doyma sınırı .. Bugün dünyadaki onlarca gıda çeşidinden daha hayırlı ve bilinen felaket boyutundakilere kıyasla en güvenlisidir.""")
h(44, 1200, """Dileyen alsın, istemeyen bıraksın!""")
